import{_ as t,o,c as a,a5 as r}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Sequence Flow — View Workspace Profile","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-13-view-workspace-profile/sequence-flow.md","filePath":"feature/agency-workspace/3-4-13-view-workspace-profile/sequence-flow.md"}'),s={name:"feature/agency-workspace/3-4-13-view-workspace-profile/sequence-flow.md"};function i(l,e,c,d,n,h){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="sequence-flow-—-view-workspace-profile" tabindex="-1">Sequence Flow — View Workspace Profile <a class="header-anchor" href="#sequence-flow-—-view-workspace-profile" aria-label="Permalink to &quot;Sequence Flow — View Workspace Profile&quot;">​</a></h1><p>&gt; Companion to <code>spec.md</code> (FR 3.4.13). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly. It does not restate business rules — see <code>spec.md</code> for those. &gt; &gt; Updated: 2026-09-25.</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Client</strong> — a Workspace member (MANAGER, CREATOR, CLIENT).</li><li><strong>System</strong> — the application service handling the request.</li><li><strong>Database</strong> — the persistent store holding Workspace and membership records.</li></ul><hr><h2 id="flow-a-—-view-workspace-details" tabindex="-1">Flow A — View Workspace details <a class="header-anchor" href="#flow-a-—-view-workspace-details" aria-label="Permalink to &quot;Flow A — View Workspace details&quot;">​</a></h2><ol><li>Client → System: open <code>/workspaces/:id/settings</code> (<code>WorkspaceSettingsPage</code>); the page calls <code>GET /api/v1/workspaces/:id</code>.</li><li>System: <code>@RequireRole({MANAGER, CREATOR, CLIENT})</code> on the controller — the caller must hold at least one of those roles somewhere, checked by <code>RequireRoleAspect</code> against a fresh DB read; otherwise rejected with 403 <code>FORBIDDEN</code>.</li><li>System → Database: look up the Workspace by its identifier; a missing Workspace is rejected with 404 <code>WORKSPACE_NOT_FOUND</code>.</li><li>System → Database: read the caller&#39;s active membership row for that same Workspace (<code>assertMember</code>, service-level check); a missing row is rejected with 403 <code>WORKSPACE_ACCESS_DENIED</code>.</li><li>System: map the Workspace to its profile, parsing the stored settings into timezone, default platforms, and report frequency.</li><li>System: when the stored settings cannot be parsed, fall back to empty settings without raising an error.</li><li>System → Client: the full Workspace profile — id, name, agencyId, slug, ownerId, settings, industry, companySize, website, phone, location, description, brandColor, logoIcon, logoUrl, tagline, foundedYear, social links, isActive, createdAt.</li><li>Client: render the Workspace profile, including the Workspace timezone.</li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>Status</th><th>Error code</th></tr></thead><tbody><tr><td>View</td><td>Caller holds none of MANAGER/CREATOR/CLIENT anywhere</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>View</td><td>Workspace does not exist</td><td>404</td><td><code>WORKSPACE_NOT_FOUND</code></td></tr><tr><td>View</td><td>Caller is not an active member of that specific Workspace</td><td>403</td><td><code>WORKSPACE_ACCESS_DENIED</code></td></tr></tbody></table><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li>Two access checks run in sequence: a coarse controller-level <code>@RequireRole</code> gate, then an explicit service-level membership check scoped to the exact Workspace in the request.</li><li>A malformed settings payload degrades to empty settings instead of failing the request.</li><li>The flow is read-only.</li></ul>',12)])])}const w=t(s,[["render",i]]);export{u as __pageData,w as default};
